// *-*-*-*-*-*-* 数据文件 *-*-*-*-*-*-*
// 存储所有的地图数据。

import * as minecraft from "@minecraft/server";
import * as lib from "./lib";

// #region 死亡类型声明

/** 死亡类型。这个死亡类型会影响显示的死亡消息。 */
export enum MurderMysteryDeathType {
    /** 被杀手杀害。 */
    MurdererStab = "murdererStab",

    /** 被杀手射杀。 */
    MurdererShot = "murdererShot",

    /** 被杀手的飞刀杀害。 */
    MurdererKnife = "murdererKnife",

    /** 射杀了自己。 */
    ShotSelf = "shotSelf",

    /** 被其他玩家杀死。 */
    Player = "player",

    /** 误杀了其他玩家。 */
    Manslaughter = "manslaughter",

    /** 掉进虚空。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    Void = "void",

    /** 掉进熔岩。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    Lava = "lava",

    /** 掉进末地传送门。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    EndPortal = "endPortal",

    /** 摔到地上。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    HitGround = "hitGround",

    /** 掉进坑里。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    Hole = "hole",

    /** 踩到陷阱。 */
    Trap = "trap",

    /** 溺死。 */
    Drowned = "drowned",

    /** 被毒药杀死。 */
    Potion = "potion",

    /** 被闪电杀死。 */
    LightningBolt = "lightningBolt",

    /** 被亡魂拖进深渊。使用该死亡方法时应该注意侦探的弓的掉落位置。 */
    DraggedByTheDead = "draggedByTheDead",

    /** 其他死因。 */
    Other = "other",
}

/** 可能导致出图的死亡方式。 */
export const deathTypeOutOfMap: MurderMysteryDeathType[] = [
    MurderMysteryDeathType.Void,
    MurderMysteryDeathType.HitGround,
    MurderMysteryDeathType.Lava,
    MurderMysteryDeathType.EndPortal,
    MurderMysteryDeathType.Hole,
    MurderMysteryDeathType.DraggedByTheDead,
];

// #endregion
// #region 地图数据类型声明

/** 地图数据。 */
export interface MurderMysteryMapData {
    /** 地图描述，包括地图的基础信息。 */
    readonly description: MurderMysteryMapDataDescription;

    /** 地图组件，代表地图使用的功能。 */
    readonly components?: MurderMysteryMapDataComponent;

    /** 地图事件，代表地图可能发生的所有事件。 */
    readonly events?: Record<string, MurderMysteryEvents>;
}

export interface MurderMysteryMapDataDescription {
    /** 地图 ID，用于地图名称的显示等。 */
    readonly id: string;

    /** 地图模式。 */
    readonly mode: "classic";

    /** 地图等待大厅信息。 */
    readonly waitHall: MurderMysteryWaitHallDescription;

    /** 地图范围。地图范围将会决定读取什么范围内的金锭点和重生点，并限制旁观模式玩家的活动范围。 */
    readonly range: {
        from: minecraft.Vector3;
        to: minecraft.Vector3;
    };

    /** 地图内可能的全部金锭点位。在实际生成时，这些金锭点位并不会全部用于生成，而是只选择玩家附近的点位生成。并且这些点位不是全部都可以生成的，而是有数量上限和概率的。这样可以确保金锭在玩家附近生成，且生成频率和位置均可控。 */
    readonly goldPoints: minecraft.Vector3[];

    /** 玩家出生点位。这同时也会影响超出的旁观者、或侦探出图后掉落的弓可能出现的位置等情况。每张地图都拥有 24 个出生点。 */
    readonly spawnPoints: minecraft.Vector3[];
}

export interface MurderMysteryWaitHallDescription {
    /** 等待大厅的位置，在开始前玩家将出生在这里。 */
    readonly location: minecraft.Vector3;

    /** 等待大厅的朝向位置，在开始前玩家出生时将面向这里。 */
    readonly facingLocation?: minecraft.Vector3;
}

// ===== 组件 =====

// #region - 组件

export interface MurderMysteryMapDataComponent {
    /** 时间组件，设定该地图使用的游戏内时间。 | 默认值：`6000` */
    readonly time?: number;

    /** 是否启用神秘药水。使用该组件决定喝下神秘药水后会使用神秘药水的随机药效，以及神秘药水的文本位置。
     * - 通常和`interaction`组件联合使用，并且需要使用带有`getMysteryPotion`的事件以使玩家能够获得神秘药水。
     */
    readonly enableMysteryPotion?: MurderMysteryEnableMysteryPotionComponent;

    /** 交互组件，定义地图可能出现的交互。默认情况下，阻止玩家与一切方块的交互。而在交互列表中的方块或位置则除外。
     * 并且，与这些方块交互还可以规定触发特殊事件。
     */
    readonly interaction?: MurderMysteryInteractionComponent[];

    /** 检查玩家进入特定区域组件。当玩家进入特定区域的时候，触发特定事件。 */
    readonly playerInArea?: MurderMysteryPlayerInAreaComponent[];

    /** 检查玩家受伤组件。当玩家受伤的时候，触发特定事件。 */
    readonly playerHurt?: MurderMysteryPlayerHurtComponent[];

    /** 游戏开始组件。当游戏开始时，触发特定事件。
     * @remarks 注意：由该组件触发的各事件响应不能获得操作的玩家。
     */
    readonly onGameStart?: MurderMysteryOnGameStartComponent;

    /** 阻止特定类型实体受到伤害组件。当特定实体受伤的时候，阻止该伤害。 */
    readonly preventDamage?: MurderMysteryPreventDamageComponent;
}

export interface MurderMysteryInteractionComponent {
    /** 允许交互的方块。 */
    blocks?: string[];

    /** 允许交互的方块坐标。注意：如果不同的交互属性有同一个坐标，只会计算第一个交互属性。 */
    at?: minecraft.Vector3[];

    /** 这次交互需要消耗多少金锭。 | 默认值：`0` */
    consume?: number;

    /** 金锭不足时是否通知玩家。 | 默认值：`true` */
    notifyPlayerWhenGoldNotEnough?: boolean;

    /** 是否仍然取消事件。通常用于只触发事件，但不进行交互的场景，例如在地图档案馆中和漏斗的交互。| 默认值：`false` */
    stillCancelEvent?: boolean;

    /** 触发何种事件。触发的事件是 {@link MurderMysteryMapData} 中的 events 对应的事件。事件的各种功能和需求见 {@link MurderMysteryEvents}。 */
    trigger?: string;
}

export interface MurderMysteryEnableMysteryPotionComponent {}

export interface MurderMysteryPlayerInAreaComponent {
    /** 待检测的区域的条件。仅当所有条件都完全符合时才会触发事件。
     * @remarks 应当指定至少一个条件，否则该组件将会始终导致事件执行。
     */
    area: {
        /** 当玩家的 X 坐标大于等于此值时，触发事件。若不指定则不检查之。 */
        xMin?: number;

        /** 当玩家的 X 坐标小于等于此值时，触发事件。若不指定则不检查之。 */
        xMax?: number;

        /** 当玩家的 Y 坐标大于等于此值时，触发事件。若不指定则不检查之。 */
        yMin?: number;

        /** 当玩家的 Y 坐标小于等于此值时，触发事件。若不指定则不检查之。 */
        yMax?: number;

        /** 当玩家的 Z 坐标大于等于此值时，触发事件。若不指定则不检查之。 */
        zMin?: number;

        /** 当玩家的 Z 坐标小于等于此值时，触发事件。若不指定则不检查之。 */
        zMax?: number;
    };

    /** 当玩家进入该区域时，触发的事件。 */
    trigger: string;
}

export interface MurderMysteryPlayerHurtComponent {
    /** 玩家因何种原因而受伤。 */
    cause: minecraft.EntityDamageCause;

    /** 当玩家受伤后，触发何种事件。 */
    trigger: string;
}

export interface MurderMysteryOnGameStartComponent {
    /** 当地图重载后，触发何种事件。 */
    trigger: string | string[];
}

export interface MurderMysteryPreventDamageComponent {
    /** 阻止何种实体受到伤害。 */
    id: string[];
}

// #endregion
// #region - 事件响应
export interface MurderMysteryEvents {
    /** 触发事件的条件。系统会首先判断该条件是否通过，仅当触发该事件时，所有的条件都通过时才能触发事件，否则无法触发事件。 */
    readonly condition?: MurderMysteryEventCondition;

    /** 设置冷却。当进入冷却状态后，系统将开始对冷却进入倒计时。 */
    readonly cooldown?: MurderMysteryCooldownEvent;

    /** 获取神秘药水事件响应，为玩家添加神秘药水。 */
    readonly getMysteryPotion?: MurderMysteryGetMysteryPotionEvent;

    /** 进入鬼屋门事件响应。进入门时有 1/3 的概率发生：
     * - 进入正确的门，玩家获得 3 个金锭；
     * - 进入错误的门，玩家掉进下面的跑酷逃生区域；
     * - 进入错误的门，玩家掉进虚空。
     *
     * 仅对具有特定结构的地图生效。
     */
    readonly intoHauntedHouseDoor?: MurderMysteryIntoHauntedHouseDoorEvent;

    /** 离开鬼屋门事件响应。只有玩家离开鬼屋门之后才能重新进入鬼屋门。 */
    readonly outOfHauntedHouseDoor?: MurderMysteryOutOfHauntedHouseDoorEvent;

    /** 放置事件响应，可放置方块、结构、实体和填充方块。 */
    readonly place?: (
        | MurderMysterySetBlockEvent
        | MurderMysteryFillBlockEvent
        | MurderMysterySetStructureEvent
        | MurderMysterySetEntityEvent
        | MurderMysterySetTextEvent
    )[];

    /** 处死玩家事件响应，以特定理由杀死玩家。 */
    readonly setPlayerDead?: MurderMysterySetPlayerDeadEvent;

    /** 传送玩家事件响应，将玩家传送到指定位置。 */
    readonly teleport?: MurderMysteryTeleportEvent;

    /** 玩家乘坐矿车事件响应，令玩家乘坐矿车到达指定位置。 */
    readonly rideMinecart?: MurderMysteryRideMinecartEvent;

    /** 事件触发成功后，如何通知触发事件的玩家。 */
    readonly notify?: lib.NotifyOptions;

    /** 事件触发成功后，如何通知全体玩家。 */
    readonly broadcast?: lib.BroadcastOptions;

    /** 事件触发成功后，以触发玩家的名义触发另一个事件。可延迟触发事件。
     * @remarks 警告：禁止调用同一个事件，例如 A 事件调用 A 事件本身！
     */
    readonly trigger?: MurderMysteryTriggerEvent;
}

export interface MurderMysteryEventCondition {
    /** 特定位置是否有特定的方块。仅当数组所有方块的条件都成立后通过。 */
    isBlock?: lib.BlockData[];

    /** 触发事件的玩家在特定高度的下方。仅当该事件有触发玩家且高度条件成立后通过。 */
    playerBelowHeight?: number;

    /** 触发事件时冷却已完毕。 */
    cooldownCompleted?: {
        type: string;
        /** 当前正在冷却的项目。可指定为键名。 */
        itemName: string;
    };
}

export interface MurderMysteryCooldownEvent {
    /** 冷却类型。 */
    type: string;

    /** 冷却时间。单位：秒。 */
    duration: number;
}

export interface MurderMysteryGetMysteryPotionEvent {
    /** 动画和悬浮文本的坐标。 */
    animationLocation: minecraft.Vector3;
}

export interface MurderMysteryIntoHauntedHouseDoorEvent {
    /** 门的位置。当玩家进入到鬼屋门时，关闭何位置的门。 */
    doorLocation: minecraft.Vector3;

    /** 岩浆跑酷房通道的玻璃位置。 */
    lavaCaveGlassLocation: minecraft.Vector3;

    /** 虚空通道的玻璃位置。 */
    voidGlassLocation: minecraft.Vector3;

    /** 虚空通道的屏障位置，强制令玩家跌到虚空。 */
    voidBarrierLocation: { from: minecraft.Vector3; to: minecraft.Vector3 };
}

export interface MurderMysteryOutOfHauntedHouseDoorEvent {}

export interface MurderMysterySetBlockEvent extends lib.BlockData {
    /** 放置类型：放置方块。 */
    type: "setBlock";
}

export interface MurderMysteryFillBlockEvent extends lib.BlockFillData {
    /** 放置类型：填充方块。 */
    type: "fillBlock";
}

export interface MurderMysterySetStructureEvent {
    /** 放置类型：放置结构。 */
    type: "setStructure";

    /** 放置何种结构。 */
    structure: string;

    /** 放置结构的位置。 */
    location: minecraft.Vector3;

    /** 放置结构的选项。 */
    options?: minecraft.StructurePlaceOptions;
}

export interface MurderMysterySetEntityEvent {
    /** 放置类型：生成实体。 */
    type: "setEntity";

    /** 生成何种实体。 */
    id: string;

    /** 生成实体的位置。 */
    location: minecraft.Vector3;

    /** 生成实体的选项。 */
    options?: minecraft.SpawnEntityOptions;
}

export interface MurderMysterySetTextEvent {
    /** 放置类型：放置悬浮文本。 */
    type: "setText";

    /** 生成何种文本。 */
    text: minecraft.RawMessage;

    /** 生成文本的位置。 */
    location: minecraft.Vector3;
}

export interface MurderMysterySetPlayerDeadEvent {
    /** 玩家的死亡类型。 */
    readonly deathType?: MurderMysteryDeathType;
}

export interface MurderMysteryTeleportEvent {
    /** 传送到的位置。 */
    location: minecraft.Vector3;

    /** 面向的位置。 */
    facingLocation?: minecraft.Vector3;
}

export interface MurderMysteryTriggerEvent {
    /** 触发的事件。 */
    id: string;

    /** 延迟多久触发指定的事件。单位：游戏刻。 | 默认值：`0` */
    delay?: number;
}

export interface MurderMysteryRideMinecartEvent {
    /** 矿车从何位置始发。 */
    from: minecraft.Vector3;

    /** 矿车到达何位置。 */
    to: minecraft.Vector3;

    /** 矿车的初始速度方向。 */
    initVelocity: minecraft.Vector3;

    /** 当矿车到站后，触发的事件。 */
    onArrival: string;
}
// #endregion

